 private FrameLayout tile(String id,int color,Runnable action){FrameLayout v=new FrameLayout(this);v.setTag(id);v.setContentDescription(null);v.setFocusable(true);v.setClickable(true);v.setDefaultFocusHighlightEnabled(false);StateListDrawable bg=new StateListDrawable();GradientDrawable focused=gradient(0xffead45c);focused.setStroke(dp(3),0xffffd86c);bg.addState(new int[]{android.R.attr.state_focused},focused);GradientDrawable pressed=gradient(0xffead45c);pressed.setStroke(dp(3),0xffffd86c);bg.addState(new int[]{android.R.attr.state_pressed},pressed);bg.addState(new int[]{},gradient(color));v.setBackground(bg);v.setClipToOutline(true);v.setOnClickListener(w->action.run());return v;}
