 private void update(){if(clock==null||destroyed)return;clock.setText(new SimpleDateFormat("HH:mm",Locale.ROOT).format(new Date()));ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);NetworkCapabilities nc=cm==null?null:cm.getNetworkCapabilities(cm.getActiveNetwork());boolean online=nc!=null&&nc.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);connection.setText(online?tx("● متصل","● Online"):tx("● غير متصل","● Offline"));connection.setTextColor(online?0xff73dfbf:0xffd2ad8f);if(loading)return;loading=true;int stamp=render;io.execute(()->{SatelliteState s=ReceiverInfoRepository.get(this).current();main.post(()->{loading=false;if(destroyed||stamp!=render)return;channel.setText(s.channelName.isEmpty()?tx("قنواتك الفضائية بلمسة واحدة","Your satellite channels in one click"):tx("آخر قناة · ","Last channel · ")+s.channelName);programme.setText(s.title);String key=s.channelName+"|"+prefs().getLong("logo_mapping_changed_at",0);if(!logoKey.equals(key)){logoKey=key;channelLogo.setImageResource(R.drawable.channel_placeholder);if(!s.channelName.isEmpty())LogoRepository.get(this).request(s.channelName,new LogoRepository.Listener(){public void channel(Bitmap b){if(!destroyed&&stamp==render&&logoKey.equals(key)&&b!=null)channelLogo.setImageBitmap(b);}public void provider(String n,Bitmap b){}});}});});}
