 private static final class HomeBackdrop extends Drawable {final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final int theme;HomeBackdrop(int t){theme=t;}public void draw(Canvas c){Rect r=getBounds();int glow=theme==1?0x22145750:theme==2?0x22154c7b:0x141c1630;paint.setShader(new LinearGradient(0,0,r.width(),r.height(),new int[]{0xff000000,0xff030306,0xff000000},null,Shader.TileMode.CLAMP));c.drawRect(r,paint);paint.setShader(new RadialGradient(r.width()*.82f,r.height()*.1f,r.width()*.75f,new int[]{glow,0x00101525},null,Shader.TileMode.CLAMP));c.drawRect(r,paint);paint.setShader(null);}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.OPAQUE;}}
